def f(inp, oh, ow):
    """Candidate: divide into equal blocks, per-block minority color (excluding bg)."""
    H,W=len(inp),len(inp[0])
    pred=[]
    for bi in range(oh):
        for bj in range(ow):
            vals=[inp[r][c] for r in range(bi*H//oh,(bi+1)*H//oh) for c in range(bj*W//ow,(bj+1)*W//ow)]
            cnt=dict(zip(*zip(*vals)))
            # most common is background; pick second-most or the odd one
            best=max(cnt.items(), key=lambda x:(-cnt[x[0]], -abs(x[0])))
            pred.append(best[0])
    return [p for p in pred]

