import os,glob,re,json,math
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
pairs=[(G[f'Demo pair {i} input'], G[f'Demo pair {i} output']) for i in range(1,9)]

# Demo 7: output [[3,0,0,0],[0,0,2,2],[2,0,0,2]]. Input has markers 3 (4 cells) at rows0 col0,2 / row5 cols0,6; 2s at... 
# Actually think: maybe output is the subgrid of marker colors after removing background/separator? 
# Or: output = shape formed by minority colors drawn on a grid?

# Try rule: find connected components of non-bg colors? Output dims vary.
# Let's analyze D7 more: bg=0, pattern color 7 (majority), markers 3 (4), 2 (12). Output contains no 7s. 
# Maybe output[i][j] = number of marker cells in some region.

# Alternative: outputs are small grids where each cell shows counts of colors within bands defined by separator lines. 
# Separator line analysis: full-row or full-col uniform lines that break structure.
def find_seps(I):
    H,W=len(I),len(I[0]); c=Counter(x for row in I for x in row); bg=max(c,key=c.get)
    sep_rows=[]
    for r in range(H):
        if len(set(I[r]))==1 and I[r][0]!=bg: sep_rows.append(r)
    sep_cols=[]
    for c in range(W):
        if all(I[r][c]==I[0][c] for r in range(H)) and I[0][c]!=bg: sep_cols.append(c)
    return sep_rows, sep_cols

for i,(I,O) in enumerate(pairs):
    sr,sc=find_seps(I)
    print(f"D{i+1}: bg={max(Counter(x for row in I for x in row), key=lambda k:Counter(x for row in I for x in row)[k])} sepr {sr} sc{sc}, out {len(O)}x{len(O[0])}")

